/// <summary>
/// VendInvoiceInfoTable table extension
/// </summary>
[ExtensionOf(tableStr(VendInvoiceInfoTable))]
final class METVendInvoiceInfoTable_Extension
{

}

Method.Source:
    /// <summary>
    /// calculate markup totals
    /// </summary>
    /// <returns>totals container</returns>
    public container metMarkupTotals()
    {
        VendInvoiceInfoLine metVendInvoiceInfoLine;
        MarkupTrans         metMarkupTrans;
        Amount              metTotalTaxAmount, metTotalAmount, metAmount;

        while select metMarkupTrans
            join metVendInvoiceInfoLine
                where metMarkupTrans.TransTableId          == tableNum(VendInvoiceInfoLine) &&
                      metMarkupTrans.TransRecId            == metVendInvoiceInfoLine.RecId &&
                      metVendInvoiceInfoLine.ParmId        == this.ParmId &&
                      metVendInvoiceInfoLine.TableRefId    == this.TableRefId
        {
            metAmount = Markup::calcMarkupAmount(metMarkupTrans, metVendInvoiceInfoLine.ReceiveNow, metVendInvoiceInfoLine.LineAmount, 0,
                metVendInvoiceInfoLine.inclTax(), NoYes::Yes, metMarkupTrans.CurrencyCode, metMarkupTrans.TransDate,
                                     0, 0, null, false, 0, '', false, false);

            metTotalTaxAmount  += Tax::calcTaxAmount(metMarkupTrans.TaxGroup, metMarkupTrans.TaxItemGroup, metMarkupTrans.TransDate,
                metMarkupTrans.CurrencyCode, metAmount, TaxModuleType::PurchInvoice);

            metTotalAmount += metAmount;
        }

        return [metTotalAmount, metTotalTaxAmount];
    }

    /// <summary>
    /// Line amounts
    /// </summary>
    /// <returns>line amounts</returns>
    public container metlineAmounts()
    {
        PurchTotals     metPurchTotals;

        metPurchTotals = PurchTotals::newParmTable(this, PurchUpdate::All, this.ParmId, '', this.Ordering);
        metPurchTotals.calc();

        return [metPurchTotals.purchBalance(), metPurchTotals.purchTaxTotal()];
    }

    /// <summary>
    /// Display method to calculate GST variance
    /// </summary>
    /// <returns>GST variance</returns>
    public display MetGSTVariance displayMetGSTVariance()
    {
        Amount metTotalMarkupTax, metTotalMarkupAmount;
        Amount metTotalLineTax, metTotalLineAmount;

        [metTotalMarkupAmount, metTotalMarkupTax] = this.metMarkupTotals();
        [metTotalLineAmount, metTotalLineTax]     = this.metLineAmounts();

        return this.MetImportGST - (metTotalLineTax - metTotalMarkupTax);
    }

    /// <summary>
    /// Display method to calculate variance
    /// </summary>
    /// <returns>Variance</returns>
    public display MetVariance displayMetVariance()
    {
        Amount metTotalMarkupTax, metTotalMarkupAmount;
        Amount metTotalLineTax, metTotalLineAmount;

        [metTotalMarkupAmount, metTotalMarkupTax] = this.metMarkupTotals();
        [metTotalLineAmount, metTotalLineTax]     = this.metLineAmounts();

        return this.MetImportAmount - (metTotalLineAmount + (metTotalLineTax - metTotalMarkupTax));
    }

    /// <summary>
    /// Variance tolerance
    /// </summary>
    /// <returns>tolerance</returns>
    public display MetVarInTol displayMETVarInTolerance()
    {
        MetVariance metVariance = this.displayMetVariance();

        return metVariance && metVariance <= VendParameters::find().ExtendedPriceToleranceAmount && metVariance >= -VendParameters::find().ExtendedPriceToleranceAmount;
    }

    /// <summary>
    /// Finds claim lines
    /// </summary>
    /// <returns>True if claim line exists; otherwise false</returns>
    public display MetClaimExist displayMETHasClaimLines()
    {
        VendInvoiceInfoLine metVendInvoiceInfoLine;

        select count(RecId) from metVendInvoiceInfoLine
            where
                metVendInvoiceInfoLine.ParmId          == this.ParmId &&
                metVendInvoiceInfoLine.TableRefId      == this.TableRefId &&
                metVendInvoiceInfoLine.MetClaimLine    == NoYes::Yes;

        return metVendInvoiceInfoLine.RecId > 0;
    }

/// <summary>
/// CB411_412_ChargeThrough
/// </summary>
/// <param name = "_vendTable"><c>VendTable</c> record to initialise fields from.</param>
void METInitFromVendTable(VendTable _vendTable)
{
    this.OrderAccount           = _vendTable.AccountNum;
    this.InvoiceAccount         = _vendTable.AccountNum;
    this.InclTax                = _vendTable.InclTax;
}

/// <summary>
/// CB411_412_ChargeThrough
/// </summary>
/// <param name = "_metVendTable"><c>METVendTable</c> record to initialise fields from.</param>
void METInitFromMETVendTable(METVendTable _metVendTable)
{
    this.METCBCTWarehouseVendor = _metVendTable.CBCTWarehouseVendor;
}

    /// <summary>
    /// CB411_412_ChargeThrough
    /// </summary>
    /// <param name = "_cbCTInvoiceHeaderTable"><c>METCBCTInvoiceHeaderTable</c> record to initialise fields from.</param>
    void METInitFromCBCTInvoiceHeaderTable(METCBCTInvoiceHeaderTable _cbCTInvoiceHeaderTable)
    {
        this.DocumentDate           = _cbCTInvoiceHeaderTable.DocumentDate;        
        this.CurrencyCode           = _cbCTInvoiceHeaderTable.CurrencyCode;
        this.TransDate              = _cbCTInvoiceHeaderTable.TransactionDate;
        this.Num                    = _cbCTInvoiceHeaderTable.TaxInvoiceNum;
        this.CashDiscCode           = _cbCTInvoiceHeaderTable.VendCashDisc;

        this.FixedDueDate           = _cbCTInvoiceHeaderTable.VendDueDate;
        this.MetImportAmount        = _cbCTInvoiceHeaderTable.VendInvoiceAmtInclGST;
        this.MetImportGST           = _cbCTInvoiceHeaderTable.VendInvoiceGSTAmount;
        this.METCBCTNumber          = _cbCTInvoiceHeaderTable.Number;

        if (_cbCTInvoiceHeaderTable.InvoiceType == METInvoiceType::ChargeThrough)
        {
            this.METChargeThrough  = NoYes::Yes;
        }
        else
        {
            this.METCrossDock      = NoYes::Yes;
        }
    }

    /// <summary>
    /// Displays the invoice total amount.
    /// </summary>
    /// <returns>Invoice total amount.</returns>
    public display AmountCur displayInvoiceTotal()
    {
        AccountingDistribution accDistribution;

        select sum(TransactionCurrencyAmount) from accDistribution
            where accDistribution.SourceDocumentHeader == this.SourceDocumentHeader;

        return accDistribution.TransactionCurrencyAmount;
    }

    /// <summary>
    /// Calculates and display match status based on the varaiance and invoice total.
    /// </summary>
    /// <returns>Match status</returns>
    public display METMatchStatus displayMetMatchStatus()
    {
        METMatchStatus matchStatus = METMatchStatus::No;
        METVendParameters metVendParameters = METVendParameters::find();

        if (metVendParameters.EnableMetcashMatchingLogic)
        {
            Amount metTotalMarkupTax, metTotalMarkupAmount;
            Amount metTotalLineTax, metTotalLineAmount;

            [metTotalMarkupAmount, metTotalMarkupTax] = this.metMarkupTotals();
            [metTotalLineAmount, metTotalLineTax]     = this.metLineAmounts();

            METTaxInvTotalsToleranceDollar taxInvTotalsToleranceDollar = metVendParameters.TaxInvTotalsToleranceDollar;
            Amount InvTotalPercAmt = (metVendParameters.TotalPriceTolerancePercentage * (metTotalLineAmount + (metTotalLineTax - metTotalMarkupTax))) / 100;
            MetVariance variance = this.MetImportAmount - (metTotalLineAmount + (metTotalLineTax - metTotalMarkupTax));

            if (metVendParameters.DisplayTotalPriceMatchIcon == DisplayTotalPriceMatchOption::GreaterThan)
            {
                if (variance <= taxInvTotalsToleranceDollar && variance <= InvTotalPercAmt)
                {
                    matchStatus = METMatchStatus::Pass;
                }
                else
                {
                    matchStatus = METMatchStatus::Fail;
                }
            }
            else if (metVendParameters.DisplayTotalPriceMatchIcon == DisplayTotalPriceMatchOption::GreaterOrLessThan)
            {
                if (variance < taxInvTotalsToleranceDollar && variance < InvTotalPercAmt)
                {
                    matchStatus = METMatchStatus::Fail;
                }
                else
                {
                    matchStatus = METMatchStatus::Pass;
                }
            }

            if (this.METEDIInvoice)
            {
                VendInvoiceInfoLine invoiceInfoLine;

                while select ItemId, ReceiveNow, LineAmount from invoiceInfoLine
                    where invoiceInfoLine.ParmId == this.ParmId
                    && invoiceInfoLine.TableRefId == this.TableRefId
                {
                    PriceTolerancePercentage percentTolerance = PurchPriceTolerance::find(invoiceInfoLine.ItemId, this.InvoiceAccount);
                    Amount lineVariance = invoiceInfoLine.displayPriceVariance() * invoiceInfoLine.ReceiveNow;
                    Amount InvTotalLinePercAmt = (percentTolerance * invoiceInfoLine.LineAmount) / 100;

                    if (lineVariance > InvTotalLinePercAmt)
                    {
                        return METMatchStatus::Fail;
                    }
                }
            }
        }

        return matchStatus;
    }

/// <summary>
/// Field will be populated with the difference between invoice total and GST.
/// </summary>
/// <returns>METInvAmtExclGST</returns>
public display METInvAmtExclGST displayInvoiceAmountExclGST()
{
    return this.MetImportAmount - this.MetImportGST;
}

/// <summary>
/// True if charge through enabled otherwise false.
/// </summary>
/// <returns>Bollean value</returns>
public boolean isChargeThroughEnabled()
{
    return (this.METCrossDock || this.METChargeThrough);
}

/// <summary>
/// True if import costing vendor active on Vendor otherwise false.
/// </summary>
/// <returns>Boolean value</returns>
public boolean isLandedCostEnabled()
{
    return VendTable::find(this.InvoiceAccount).ITMImportCostingVendor;
}
